from __future__ import annotations

import dataclasses
from typing import Any

import pytest

import llm_router as package
from llm_router import (
    LLMRouter,
    LLMRouterError,
    Model,
    Provider,
    RouterProfile,
)
from tests.llm_router.support.fault_server import (
    ScriptedHTTPServer,
    ScriptedResponse,
)
from tests.llm_router.support.workers.retry import (
    openai_chat_path,
    openai_error_response,
    openai_success_response,
)
from tests.llm_router.support.workers.worker_patches import patched_openai_sdk

pytestmark = pytest.mark.verification_kind("unit")

_OPENAI_PATH = openai_chat_path()


@pytest.fixture
def single_attempt_config() -> Any:
    original = package.get_config()
    policy = dataclasses.replace(original.defaults.policy, max_attempts=1)
    defaults = dataclasses.replace(original.defaults, policy=policy)
    package.install_config(dataclasses.replace(original, defaults=defaults))
    yield package.get_config()
    package.install_config(original)


def _router(monkeypatch: pytest.MonkeyPatch) -> LLMRouter:
    for route_id in (1, 2):
        monkeypatch.setenv(f"OPENROUTER_API_KEY_{route_id}", f"value-{route_id}")
    profiles = [
        RouterProfile(
            provider=Provider.OPENROUTER,
            model=Model.DEEPSEEK_V3,
            key_id=route_id,
            max_attempts=None,
        )
        for route_id in (1, 2)
    ]
    return LLMRouter(
        profiles,
        max_attempts=None,
        shuffle_fallbacks=False,
        round_robin_start=False,
    )


def _responses() -> list[ScriptedResponse]:
    headers = {"Content-Type": "application/json"}
    return [
        ScriptedResponse(
            status_code=400,
            headers=headers,
            body=openai_error_response(status_code=400, message="first-failed"),
        ),
        ScriptedResponse(
            status_code=200,
            headers=headers,
            body=openai_success_response(text="second-route"),
        ),
    ]


@pytest.mark.verifies("REQ_REQUEST_OVERRIDE_PRECEDENCE[revision==1]")
def test_null_router_and_route_max_attempts_keep_config_default(
    monkeypatch: pytest.MonkeyPatch,
    single_attempt_config: Any,
) -> None:
    assert single_attempt_config.policy.max_attempts == 1
    router = _router(monkeypatch)
    with (
        ScriptedHTTPServer(
            port=0, routes={("POST", _OPENAI_PATH): _responses()}
        ) as server,
        patched_openai_sdk(
            forced_base_url=f"{server.base_url}/v1", disable_sdk_retries=True
        ),
        pytest.raises(LLMRouterError, match=r"status code 400"),
    ):
        router.query("hello", temperature=None)
